namespace {
QString text(double x){return QString::number(x,'g',17);}
QTableWidget* table(QString name,QStringList headers){auto* t=new QTableWidget(0,headers.size());t->setObjectName(name);t->setHorizontalHeaderLabels(headers);t->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);t->horizontalHeader()->setStretchLastSection(true);t->setAlternatingRowColors(true);t->setSelectionBehavior(QAbstractItemView::SelectRows);return t;}
void cell(QTableWidget* t,int r,int c,double v){t->setItem(r,c,new QTableWidgetItem(text(v)));}
double value(QTableWidget* t,int r,int c){bool ok=false;const auto* item=t->item(r,c);double v=item?uiNumber(item->text(),&ok):0;if(!ok)throw std::invalid_argument("В числовых ячейках нужны конечные числа; принимаются точка и запятая");return v;}
double input(QLineEdit* b){bool ok=false;const auto v=uiNumber(b->text(),&ok);if(!ok)throw std::invalid_argument("Нужно конечное число; допускаются точка, запятая и научная запись");return v;}
void targetCells(QTableWidget* t,int r,DesignTarget target,bool manufacturing=false){auto* p=new QComboBox;for(int i=0;i<=int(DesignParameter::XY03);++i){DesignTarget x{DesignParameter(i),0};if(manufacturing&&(fieldTarget(x)||x.parameter==DesignParameter::ObjectDistance||x.parameter==DesignParameter::PupilDiameter))continue;p->addItem(QString::fromUtf8(designParameterName(x.parameter)),i);}p->setCurrentIndex(p->findData(int(target.parameter)));t->setCellWidget(r,0,p);cell(t,r,1,double(target.index+1));}
DesignTarget target(QTableWidget* t,int r){auto* p=qobject_cast<QComboBox*>(t->cellWidget(r,0));if(!p||p->currentIndex()<0)throw std::invalid_argument("Выберите параметр");const double index=value(t,r,1);if(index<1||index>500||std::floor(index)!=index)throw std::invalid_argument("Номер поверхности/поля: целое от 1 до 500");DesignTarget out{DesignParameter(p->currentData().toInt()),size_t(index-1)};if(!surfaceTarget(out)&&!fieldTarget(out))out.index=0;return out;}
void configRow(QTableWidget* t,const ConfigurationValue& v){const int r=t->rowCount();t->insertRow(r);targetCells(t,r,v.target);cell(t,r,2,v.value);auto* flag=new QTableWidgetItem;flag->setFlags(Qt::ItemIsEnabled|Qt::ItemIsUserCheckable);flag->setCheckState(v.variable?Qt::Checked:Qt::Unchecked);t->setItem(r,3,flag);cell(t,r,4,v.lower);cell(t,r,5,v.upper);cell(t,r,6,v.step);}
void tolRow(QTableWidget* t,const ToleranceOperand& v){const int r=t->rowCount();t->insertRow(r);targetCells(t,r,v.target,true);cell(t,r,2,v.amplitude);cell(t,r,3,v.mean);auto* distribution=new QComboBox;distribution->addItems({"Равномерное ±a","Нормальное σ=a/3"});distribution->setCurrentIndex(int(v.distribution));t->setCellWidget(r,4,distribution);}
void compRow(QTableWidget* t,const Compensator& v){const int r=t->rowCount();t->insertRow(r);targetCells(t,r,v.target,true);cell(t,r,2,v.lower);cell(t,r,3,v.upper);cell(t,r,4,v.step);}
void writeFile(const QString& path,const QByteArray& bytes){QSaveFile f(path);if(!f.open(QIODevice::WriteOnly)||f.write(bytes)!=bytes.size()||!f.commit())throw std::runtime_error("Не удалось записать файл");}
QString score(const std::optional<double>& v){return v?text(*v):"недопустимо";}
}
