StudyEditor::~StudyEditor(){if(cancel_)cancel_->store(true);watcher_.waitForFinished();}
void StudyEditor::reject(){if(busy_){closing_=true;cancel_->store(true);message_->setText("Останавливаю расчёт…");return;}QDialog::reject();}
void StudyEditor::guard(const std::function<void()>& fn){try{if(busy_)return;message_->clear();fn();}catch(const std::exception& e){message_->setText(QString::fromUtf8(e.what()));}}
void StudyEditor::loadConfigurations(){QSignalBlocker block(configs_);configs_->clear();for(const auto& c:project_.configurations)configs_->addItem(QString::fromStdString(c.name));selected_=std::clamp(selected_,-1,int(project_.configurations.size())-1);if(selected_<0&&!project_.configurations.empty())selected_=0;configs_->setCurrentIndex(selected_);loadState(selected_);}
void StudyEditor::loadState(int index){selected_=index;values_->setRowCount(0);materials_->setRowCount(0);name_->setEnabled(index>=0);weight_->setEnabled(index>=0);name_->clear();if(index<0)return;const auto& c=project_.configurations.at(index);name_->setText(QString::fromStdString(c.name));weight_->setText(text(c.weight));for(const auto& v:c.values)configRow(values_,v);for(const auto& m:c.materials){int r=materials_->rowCount();materials_->insertRow(r);cell(materials_,r,0,double(m.surface+1));materials_->setItem(r,1,new QTableWidgetItem(QString::fromStdString(m.material)));}}
void StudyEditor::storeState(){if(selected_<0)return;auto c=project_.configurations.at(selected_);c.name=name_->text().trimmed().toStdString();c.weight=input(weight_);c.values.clear();c.materials.clear();for(int r=0;r<values_->rowCount();++r)c.values.push_back({target(values_,r),value(values_,r,2),values_->item(r,3)->checkState()==Qt::Checked,value(values_,r,4),value(values_,r,5),value(values_,r,6)});
 for(int r=0;r<materials_->rowCount();++r){const double index=value(materials_,r,0);if(index<1||index>500||std::floor(index)!=index||!materials_->item(r,1))throw std::invalid_argument("Неверная ссылка материала");c.materials.push_back({size_t(index-1),materials_->item(r,1)->text().trimmed().toStdString()});}auto cs=project_.configurations;cs[selected_]=c;auto errors=validateConfigurations({project_.system,project_.catalog},cs);if(!errors.empty())throw std::invalid_argument(errors.front());project_.configurations=cs;}
void StudyEditor::loadTolerance(){auto t=project_.tolerance.value_or(TolerancePlan{});tolerances_->setRowCount(0);compensators_->setRowCount(0);for(const auto& v:t.operands)tolRow(tolerances_,v);for(const auto& v:t.compensators)compRow(compensators_,v);QSignalBlocker block(correlation_);const int n=int(t.operands.size());correlation_->setRowCount(n);correlation_->setColumnCount(n);QStringList labels;for(int i=0;i<n;++i){labels<<"T"+QString::number(i+1);for(int j=0;j<n;++j)cell(correlation_,i,j,t.correlation.empty()?(i==j?1:0):t.correlation.at(i).at(j));}correlation_->setHorizontalHeaderLabels(labels);correlation_->setVerticalHeaderLabels(labels);samples_->setValue(int(t.samples));iterations_->setValue(int(t.compensationIterations));seed_->setText(QString::number(t.seed));limit_->setText(text(t.limit));}
Project StudyEditor::read(){storeState();auto p=project_;if(tolerances_->rowCount()==0){p.tolerance.reset();return p;}TolerancePlan t;t.samples=size_t(samples_->value());t.compensationIterations=size_t(iterations_->value());t.limit=input(limit_);bool ok=false;t.seed=seed_->text().toULongLong(&ok);if(!ok)throw std::invalid_argument("Seed: целое без знака");
 for(int r=0;r<tolerances_->rowCount();++r)t.operands.push_back({target(tolerances_,r),value(tolerances_,r,2),value(tolerances_,r,3),ToleranceDistribution(qobject_cast<QComboBox*>(tolerances_->cellWidget(r,4))->currentIndex())});
 for(int r=0;r<compensators_->rowCount();++r)t.compensators.push_back({target(compensators_,r),value(compensators_,r,2),value(compensators_,r,3),value(compensators_,r,4)});
 for(int i=0;i<correlation_->rowCount();++i){std::vector<double> row;for(int j=0;j<correlation_->columnCount();++j)row.push_back(value(correlation_,i,j));t.correlation.push_back(row);}auto errors=t.validate({p.system,p.catalog},p.configurations);if(!errors.empty())throw std::invalid_argument(errors.front());p.tolerance=t;return p;
}
void StudyEditor::launch(int kind){auto p=read();if(kind==2&&!p.tolerance)throw std::invalid_argument("Добавьте хотя бы один допуск");project_=p;cancel_=std::make_shared<std::atomic<bool>>(false);done_=std::make_shared<std::atomic<size_t>>(0);total_=std::make_shared<std::atomic<size_t>>(1);auto cancel=cancel_;auto done=done_,total=total_;busy_=true;tabs_->setEnabled(false);save_->setEnabled(false);progress_->setRange(0,0);progress_->show();timer_->start(100);message_->setText("Расчёт… Можно остановить без применения частичного результата.");
 watcher_.setFuture(QtConcurrent::run([p,kind,cancel,done,total]()mutable{StudyOutcome out;out.project=p;try{auto plan=p.optimization.value_or(defaultOptimization(p.system,p.catalog));auto progress=[&](size_t i,size_t n,double){done->store(i);total->store(n);return !cancel->load();};
  if(kind==2){auto report=runTolerances({p.system,p.catalog},p.configurations,plan,*p.tolerance,progress);out.cancelled=report.cancelled;out.report=report;out.text=QString("Критерий: максимум функции качества по состояниям. Предел: %1\nНоминал: %2\n\nБез компенсации: %3/%4 = %5%; Wilson 95% [%6%; %7%]\nС компенсацией: %8/%9 = %10%; Wilson 95% [%11%; %12%]\n").arg(p.tolerance->limit).arg(report.nominal).arg(report.before.accepted).arg(report.before.total).arg(100*report.before.fraction).arg(100*report.before.lower).arg(100*report.before.upper).arg(report.after.accepted).arg(report.after.total).arg(100*report.after.fraction).arg(100*report.after.lower).arg(100*report.after.upper);
   out.text+="\nКритические параметры: индекс T; качество при −a / +a после компенсации\n";auto sensitivity=report.sensitivities;std::stable_sort(sensitivity.begin(),sensitivity.end(),[](const auto& a,const auto& b){return a.impact>b.impact;});for(const auto& v:sensitivity)out.text+=QString("T%1 %2: %3 / %4\n").arg(v.operand+1).arg(QString::fromUtf8(designParameterName(p.tolerance->operands[v.operand].target.parameter)),score(v.minus.after),score(v.plus.after));
   out.text+="\nСходимость выхода годных: N; доля; интервал 95%\n";for(const auto& y:report.convergence)out.text+=QString("%1  %2  [%3; %4]\n").arg(y.total).arg(y.fraction).arg(y.lower).arg(y.upper);out.text+="\nНедопустимые образцы входят в знаменатель как негодные. Доверительный интервал оценивает статистику заданной модели, а не ошибки оптической модели.\n";
  }else{OpticalDesign d{p.system,p.catalog};if(kind==1){auto r=optimizeConfigurations(d,p.configurations,plan,progress);out.cancelled=r.cancelled;out.project.system=d.system;out.project.catalog=d.catalog;out.project.configurations=p.configurations;out.text=QString("Ограниченный координатный поиск: %1 → %2; %3 оценок\n").arg(r.before).arg(r.after).arg(r.evaluations);}if(!out.cancelled){auto e=evaluateConfigurations(d,p.configurations,plan);out.text+=QString("Общая функция качества: %1\nКвадратичное усреднение по весам состояний.\n\n").arg(e.score);for(size_t i=0;i<e.scores.size();++i){if(cancel->load()){out.cancelled=true;break;}auto state=p.configurations.empty()?Configuration{}:p.configurations[i];const auto resolved=configurationDesign(d,state);out.text+=QString("%1 · вес %2 · качество %3\n").arg(QString::fromStdString(state.name)).arg(state.weight).arg(e.scores[i]);for(size_t f=0;f<resolved.system.fields.size();++f){auto sp=spot(resolved.system,resolved.catalog,resolved.system.fields[f],plan.pupilGrid);out.text+=QString("  Поле %1: RMS %2 мкм; лучей %3/%4\n").arg(f+1).arg(1000*sp.rms).arg(sp.samples.size()).arg(sp.launched);}}}}
 }catch(const std::exception& e){out.error=QString::fromUtf8(e.what());}out.cancelled=out.cancelled||cancel->load();return out;}));
}
void StudyEditor::preview(){auto p=read();if(selected_<0)throw std::invalid_argument("Выберите состояние");auto standalone=configurationProject(p,size_t(selected_));auto* w=new Window;w->setAttribute(Qt::WA_DeleteOnClose);w->setProject(standalone);w->show();w->recalculate();}
void StudyEditor::exportReport(bool csv){if(!report_)throw std::invalid_argument("Сначала выполните расчёт допусков");if(serializeProject(read())!=serializeProject(reportProject_))throw std::invalid_argument("Параметры изменились; повторите расчёт перед выгрузкой");auto path=QFileDialog::getSaveFileName(this,"Отчёт допусков",{},csv?"CSV (*.csv)":"JSON (*.json)");if(path.isEmpty())return;
 if(!csv){auto json=toleranceReportJson(*report_);json["project"]=QJsonDocument::fromJson(serializeProject(reportProject_)).object();writeFile(path,QJsonDocument(json).toJson());return;}QByteArray bytes="sample,before,after,passed";for(size_t i=0;i<reportProject_.tolerance->operands.size();++i)bytes+=",delta_T"+QByteArray::number(i+1);for(size_t i=0;i<reportProject_.tolerance->compensators.size();++i)bytes+=",correction_C"+QByteArray::number(i+1);bytes+='\n';
 for(size_t i=0;i<report_->samples.size();++i){const auto& s=report_->samples[i];bytes+=QByteArray::number(i+1)+","+(s.before?text(*s.before).toUtf8():QByteArray())+","+(s.after?text(*s.after).toUtf8():QByteArray())+","+(s.after&&*s.after<=reportProject_.tolerance->limit?"1":"0");for(double d:s.deltas)bytes+=","+text(d).toUtf8();for(double d:s.corrections)bytes+=","+text(d).toUtf8();bytes+='\n';}writeFile(path,bytes);
}
void StudyEditor::exportSample(){if(!report_||report_->cancelled)throw std::invalid_argument("Нет завершённого отчёта");if(serializeProject(read())!=serializeProject(reportProject_))throw std::invalid_argument("Параметры изменились; повторите расчёт");const size_t i=size_t(sampleIndex_->value()-1);if(i>=report_->samples.size())throw std::invalid_argument("Образца с таким номером нет");auto p=realizedProject(reportProject_,report_->samples[i],size_t(stateIndex_->value()-1));auto path=QFileDialog::getSaveFileName(this,"Реализованный образец",{},"Optical CAD (*.optcad)");if(!path.isEmpty())saveProject(path,p);}
